INSERT INTO `oa_offical_doc` (`id`, `red_head_id`, `title`, `content`, `secret_level`, `doc_dept_name`, `secret_period`, `emergent_level`, `public_category`, `doc_code`, `year`, `num`, `qizi`, `draft_status`, `send_status`, `url`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`, `bill_type`, `bill_code`, `flow_key`, `flow_ins_id`, `submit_time`, `status`, `tenant_id`, `html`, `send_date`, `receive_dept_id`) VALUES (1, 1, '关于xxxxx的决定', '<p>经研究决定： </p><p>任命王仙芝为成都分公司总经理，徐凤年不再担任成都分公司总经理职务。 </p><p>任命杨过为北京分公司总经理，杨阳为北京分公司部门副经理。</p><p>任命周伯通为后勤部总经理，兼任办公室主任，兼任开发部经理，兼任销售部经理，兼任人事部经理。</p><p>特此决定</p>', NULL, NULL, NULL, NULL, NULL, NULL, 2023, 1, '企推信息xxxx企字', '1', '0', '/profile/oa/officalDoc/pdf/2023/1/关于xxxxx的决定_seal.pdf', 1, '2023-11-05 11:03:24', 1, '2024-02-29 09:54:33', NULL, 'offical_doc', 'WBSW202401280001', '', '', NULL, '0', 1, '<html><body><div style=\'padding:40px;\'><div style=\'text-align: center;padding-top:20px\'><span style=\'color:#FF0000; font-size: 40px;\'><strong>企推信息科技有限公司文件</strong></span></div><div style=\'text-align: center;padding:25px 25px 3px 25px\'><span style=\'color: #222222; font-size: 16px;\'>企推信息xxxx企字（2023）第【1】号</span></div><table style=\'border-bottom:2px solid #FF0000;width:100%;\'><tr style=\'width:100%\'><td style=\'100%\'>&nbsp;</td></tr></table><div style=\'text-align: center;padding: 25px 25px 0px 25px;\'><span style=\'color: #222222; font-size: 18px;font-weight:900;\'>关于xxxxx的决定</span></div><br /><div style=\'line-height:36px;font-size:20px;text-indent:40px;margin-top:-10px;\'>经研究决定： </div><div style=\'line-height:36px;font-size:20px;text-indent:40px;margin-top:-10px;\'>任命王仙芝为成都分公司总经理，徐凤年不再担任成都分公司总经理职务。 </div><div style=\'line-height:36px;font-size:20px;text-indent:40px;margin-top:-10px;\'>任命杨过为北京分公司总经理，杨阳为北京分公司部门副经理。</div><div style=\'line-height:36px;font-size:20px;text-indent:40px;margin-top:-10px;\'>任命周伯通为后勤部总经理，兼任办公室主任，兼任开发部经理，兼任销售部经理，兼任人事部经理。</div><div style=\'line-height:36px;font-size:20px;text-indent:40px;margin-top:-10px;\'>特此决定</div><div style=\'position: relative;padding-top:50px;\'><div style=\'text-align: right;font-size:20px;padding-right:50px;line-height:36px;\'>山东企推信息科技有限公司</div><div style=\'text-align: right;font-size:20px;padding-right:50px;line-height:36px;\'>2023年11月10日</div><div id=\'seal\'></div></div></div></body></html>', '2023-11-10 00:00:00', '101,102,200,202');
