INSERT INTO `pg_task` (`id`, `project_id`, `model_name`, `task_name`, `priority`, `summary`, `des`, `duty_person`, `assistants`, `start_time`, `end_time`, `status`, `progress`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (12, 1, '会议管理', '会议管理', 'gao', NULL, '<table style=\"width: auto;\"><tbody><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"124\">会议发起</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">设置会议内容、与会人员、会议地点和会议记录的读写权限</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">暂存会议查询</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">查询未发起的或尚未进行的会议</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">待我参加的会议</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">显示待参加会议列表</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">我已参加的会议</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">显示已参加会议列表</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">新建会议纪要</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">可在线输入会议纪要内容，并进行上传，可考虑上传文档附件</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">会议纪要查询</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">查询会议纪要</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">会议室状态查询</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">查询会议室空闲状态，可挑选空闲会议室进行会议</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">会议室设置</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">设置会议室基本信息，位置及可容纳人员</td></tr></tbody></table><p><br></p>', 1, NULL, NULL, NULL, '0', 0, 1, '2023-08-08 09:12:16', NULL, NULL, NULL);
INSERT INTO `pg_task` (`id`, `project_id`, `model_name`, `task_name`, `priority`, `summary`, `des`, `duty_person`, `assistants`, `start_time`, `end_time`, `status`, `progress`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (13, 1, '办公用品', '办公用品登记，领用', 'gao', NULL, '<table style=\"width: auto;\"><tbody><tr><p>办公物品列1表</p><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">录入新的办公物品，并在列表进行编辑管理</td><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">领用登记</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">登记不同人员领用的物品</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">在库查询</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">查询现有的物品</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">领用查询</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">查询人员的领用物品记录</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">物品类别</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">对物品进行分类</td></tr><p><br></p></tr></tbody></table><p><br></p>', 1, NULL, NULL, NULL, '0', 0, 1, '2023-08-08 09:13:54', NULL, '2023-08-08 10:22:01', NULL);
INSERT INTO `pg_task` (`id`, `project_id`, `model_name`, `task_name`, `priority`, `summary`, `des`, `duty_person`, `assistants`, `start_time`, `end_time`, `status`, `progress`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (14, 1, '固定资产', '固定资产管理', 'gao', NULL, '<table style=\"width: auto;\"><tbody><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"124\">资产登记···</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">登记现有资产</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">资产查询</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">对全部资产进行查询</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><s>资产折旧</s></td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\"><s>对资产进行折旧处理，设置不同的折旧方式</s></td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">资产类别</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">对资产进行分类</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">资产管理</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">对固定资产进行调拨、报废、盘点等</td></tr></tbody></table><p><br></p>', 1, NULL, NULL, NULL, '0', 0, 1, '2023-08-08 09:14:12', NULL, '2023-08-08 10:22:20', NULL);
INSERT INTO `pg_task` (`id`, `project_id`, `model_name`, `task_name`, `priority`, `summary`, `des`, `duty_person`, `assistants`, `start_time`, `end_time`, `status`, `progress`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (15, 1, '员工信息档案', '员工信息档案', 'gao', NULL, '<table style=\"width: auto;\"><tbody><tr><td colSpan=\"1\" rowSpan=\"6\" width=\"145\">员工信息档案</td><td colSpan=\"1\" rowSpan=\"2\" width=\"124\">新增员工档案</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">新增企业人事档案，根据预设的档案各个字段进行填写</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">整个档案内的信息分成不同类目，基本信息、证照信息、学习经历等</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">档案管理</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">管理人员档案的信息，可以进行新建、修改、删除操作</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">档案查找</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">可根据姓名查找对应的档案</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">档案一览</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">显示当前所有档案的台账</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">保存期限</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">离职员工离职后（离职申请通过后）自动进行档案清理</td></tr></tbody></table><p><br></p>', 1, NULL, NULL, NULL, '0', 0, 1, '2023-08-08 09:15:03', NULL, NULL, NULL);
INSERT INTO `pg_task` (`id`, `project_id`, `model_name`, `task_name`, `priority`, `summary`, `des`, `duty_person`, `assistants`, `start_time`, `end_time`, `status`, `progress`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (16, 1, '人事调动', '人事调动', 'gao', '人事调动', '<table style=\"width: auto;\"><tbody><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"124\">员工入职</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">员工可以发起入职申请，记录人员入职的基础信息</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">人事调动</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">记录人员的调动记录</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">职位变更</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">记录人员的职位变更信息</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">培训记录</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">记录人员的培训状况</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">奖惩记录</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">记录人员的奖惩状况</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">员工评价</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">记录领导对该员工的评价信息</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">人事合同</td><td colSpan=\"1\" rowSpan=\"1\" width=\"404\">设置员工的人事合同</td></tr></tbody></table><p><br></p>', 1, NULL, NULL, NULL, '0', 0, 1, '2023-08-08 09:15:33', NULL, NULL, NULL);
INSERT INTO `pg_task` (`id`, `project_id`, `model_name`, `task_name`, `priority`, `summary`, `des`, `duty_person`, `assistants`, `start_time`, `end_time`, `status`, `progress`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (17, 1, '日程管理', '日程管理完善，可以提交给他人，可以查看他人的日程', 'gao', NULL, '<p><br></p>', 1, NULL, NULL, NULL, '0', 0, 1, '2023-08-08 09:16:16', NULL, '2023-08-08 09:24:48', NULL);
INSERT INTO `pg_task` (`id`, `project_id`, `model_name`, `task_name`, `priority`, `summary`, `des`, `duty_person`, `assistants`, `start_time`, `end_time`, `status`, `progress`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (18, 1, '用车管理', '车辆调度、车辆档案、车辆维修、车辆保养、车辆报废', 'gao', NULL, '<p>车辆进行管理，包括用车申请、车辆调度、车辆档案、车辆维修、车辆保养、车辆报废等功能。</p>', 1, NULL, NULL, NULL, '0', 0, 1, '2023-08-08 09:26:19', NULL, NULL, NULL);
